select e.titulo, count(p.id) as preguntas from public.evaluaciones e join public.evaluacion_preguntas p on p.evaluacion_id=e.id where e.id in ('33da7371-8264-5a6c-a6b0-b81a63e38793','2273cb7e-f0d5-594d-a3df-e1f5e9ba7ec2') group by e.id,e.titulo order by e.titulo;
